// === PARSER STATE ===

/**
 * @brief Returns whether a token of given type owns heap text in value.text
 */
static bool token_has_text(TokenType type) {
  // Must match the lexer contract (see lexer_source_next)
  switch (type) {
    case IDENT:
    case STRING:
    case TRIPLE_STRING:
    case S_STRING_START:
    case S_STRING_END:
    case TRIPLE_S_STRING_START:
    case TRIPLE_S_STRING_END:
      return true;
    default:
      return false;
  }
}

/**
 * @brief Frees the text owned by a token (if any)
 */
static void token_free(Token* token) {
  if (token_has_text(token->type)) {
    free(token->value.text);
    token->value.text = NULL;
  }
}

void parser_init(Ctx* ctx, TokenSourceNext next, void* source) {
  Parser* parser = TRY_MALLOC(sizeof(*parser));
  *parser = (Parser){
      .next = next,
      .source = source,
      .current = {.type = EOF_TOKEN},
      .has_peeked = false,
      .indents = ARRAY_EMPTY,
      .pending_closes = 0,
  };

  // Registered before anything that can throw, so ctx_free can release it
  ctx->parser = parser;

  // Top level, the bottom of the indentation stack
  array_append(ctx, &parser->indents, 0);

  parser_advance(ctx, parser);
}

void parser_cleanup(Ctx* ctx) {
  Parser* parser = ctx->parser;
  if (parser == NULL)
    return;

  ctx->parser = NULL;
  token_free(&parser->current);
  if (parser->has_peeked)
    token_free(&parser->peeked);
  array_free(&parser->indents);
  free(parser);
}

// === TOKEN LAYER ===

/**
 * @brief Reads the next token the parser should see from the token source
 */
static Token fetch_token(Ctx* ctx, Parser* parser) {
  // Deliver block closes left over from a drop by more than one level
  if (parser->pending_closes > 0) {
    parser->pending_closes--;
    return parser->pending_close;
  }

  while (true) {
    Token token = parser->next(ctx, parser->source);
    if (token.type == WHITESPACE)
      continue;

    // PLACEHOLDER (guidance/parser-structure/GLOSSARY.md, Raw indent): if the
    // lexer ends up emitting DEDENT, only this translation changes.
    // The end of file closes every open block, as a raw indent of 0 would.
    bool closes_all = token.type == EOF_TOKEN && parser->indents.count > 1;
    if (token.type != INDENT && !closes_all)
      return token;

    IndentStack* indents = &parser->indents;
    int indentation = closes_all ? 0 : token.value.integer;
    int enclosing = indents->data[indents->count - 1];

    // Same block, the raw indent is not visible to the parser
    if (indentation == enclosing)
      continue;

    // Deeper, block open
    if (indentation > enclosing) {
      array_append(ctx, indents, indentation);
      return token;
    }

    // Shallower, one block close per closed level
    size_t closes = 0;
    while (indents->data[indents->count - 1] > indentation) {
      indents->count--;
      closes++;
    }
    if (indents->data[indents->count - 1] != indentation)
      THROW(E_SYNTAX_ERROR,
            "%d:%d: syntax error: indentation of %d matches no enclosing block",
            token.line, token.column, indentation);

    // The end of file itself is read again after the closes
    Token close = {.type = INDENT, .line = token.line, .column = token.column};
    parser->pending_closes = closes - 1;
    parser->pending_close = close;
    return close;
  }
}

void parser_advance(Ctx* ctx, Parser* parser) {
  token_free(&parser->current);

  // A peeked token was already fetched (and translated), it comes next
  if (parser->has_peeked) {
    parser->current = parser->peeked;
    parser->has_peeked = false;
    return;
  }

  parser->current = fetch_token(ctx, parser);
}

void parser_expect(Ctx* ctx, Parser* parser, TokenType type) {
  if (parser->current.type != type)
    parser_syntax_error(ctx, parser, parser_token_name(type));
  parser_advance(ctx, parser);
}

bool parser_accept(Ctx* ctx, Parser* parser, TokenType type) {
  if (parser->current.type != type)
    return false;
  parser_advance(ctx, parser);
  return true;
}

void parser_syntax_error(Ctx* ctx, const Parser* parser, const char* expected) {
  const Token* token = &parser->current;
  THROW(E_SYNTAX_ERROR, "%d:%d: syntax error: expected %s, got %s", token->line,
        token->column, expected, parser_token_name(token->type));
}

const char* parser_token_name(TokenType type) {
  static const char* const names[] = {
      [IDENT] = "identifier",
      [AT_MAIN] = "@main",
      [IMPORT] = "import",
      [DEF] = "def",
      [VAL] = "val",
      [VAR] = "var",
      [RETURN] = "return",
      [IF] = "if",
      [THEN] = "then",
      [ELSE] = "else",
      [WHILE] = "while",
      [DO] = "do",
      [TYPE_INT] = "Int",
      [TYPE_DOUBLE] = "Double",
      [TYPE_STRING] = "String",
      [TYPE_UNIT] = "Unit",
      [FOR] = "for",
      [TYPE_BOOL] = "Boolean",
      [BOOL_TRUE] = "true",
      [BOOL_FALSE] = "false",
      [NUMBER_INT] = "integer literal",
      [NUMBER_DOUBLE] = "double literal",
      [STRING] = "string literal",
      [TRIPLE_STRING] = "triple-quoted string",
      [S_STRING_START] = "start of interpolated string",
      [S_STRING_END] = "end of interpolated string",
      [TRIPLE_S_STRING_START] = "start of triple-quoted interpolated string",
      [TRIPLE_S_STRING_END] = "end of triple-quoted interpolated string",
      [OPERATOR_PLUS] = "+",
      [OPERATOR_MINUS] = "-",
      [OPERATOR_MULTIPLY] = "*",
      [OPERATOR_DIVIDE] = "/",
      [ASSIGN] = "=",
      [COMPARISON_EQ] = "==",
      [COMPARISON_NEQ] = "!=",
      [COMPARISON_G] = ">",
      [COMPARISON_L] = "<",
      [COMPARISON_GE] = ">=",
      [COMPARISON_LE] = "<=",
      [BOOL_AND] = "&&",
      [BOOL_OR] = "||",
      [BOOL_NEG] = "!",
      [L_PAREN] = "(",
      [R_PAREN] = ")",
      [COMMA] = ",",
      [PERIOD] = ".",
      [COLON] = ":",
      [SEMICOLON] = ";",
      [CONTROL_ARROW] = "=>",
      [INDENT] = "change of indentation",
      [EOL_TOKEN] = "end of line",
      [WHITESPACE] = "whitespace",
      [EOF_TOKEN] = "end of file",
  };

  if ((size_t)type >= sizeof(names) / sizeof(*names) || names[type] == NULL)
    return "unknown token";
  return names[type];
}

const Token* parser_peek(Ctx* ctx, Parser* parser) {
  // TODO(parser author): fill parser->peeked with fetch_token (so the peeked
  // token is translated like any other) and set has_peeked; parser_advance
  // already moves to the peeked token
  (void)parser;
  THROW(E_INTERNAL_ERROR, "parser_peek is not implemented yet");
  return NULL;  // unreachable
}

