/**
 * @brief Reads the next token from the lexer (TokenSourceNext).
 *
 * PLACEHOLDER until the lexer exposes its next-token function; then replace the
 * body with a call to it. Contract the parser relies on
 * (guidance/parser-structure/adr/0002):
 *  - lexical errors are thrown by the lexer (E_LEXER_ERROR),
 *  - the returned token is owned by the parser; value.text is heap memory
 *    (freed with free()) exactly for the types in token_has_text,
 *  - every source line starts with an INDENT whose value.integer is the line's
 *    indentation, lines in column 0 included,
 *  - after the end of input, EOF_TOKEN is returned on every call.
 */
static Token lexer_source_next(Ctx* ctx, void* source) {
  (void)source;
  THROW(E_INTERNAL_ERROR, "the lexer's next-token function is not available");
  return (Token){.type = EOF_TOKEN};  // unreachable
}

void parser_parse(Ctx* ctx, Lexer* lexer) {
  parser_init(ctx, lexer_source_next, lexer);

  // The root is stored in ctx before parsing, so a partly built tree is freed
  // by ctx_free when an error is thrown
  AstNode* root;
  ast_node_create(ctx, &root);
  ast_node_set_type(root, AST_NODE_PROGRAM);
  ctx->ast = root;

  // TODO(parser author): call the start nonterminal function here

  parser_cleanup(ctx);
}
